import { UserPlus, Mail, Link2, CheckCircle } from "lucide-react";

const steps = [
  {
    icon: UserPlus,
    step: "01",
    title: "Enter Your Email",
    description:
      "User visits the login page and enters their email address. No password field needed.",
    color: "from-primary/20 to-accent/20",
  },
  {
    icon: Link2,
    step: "02",
    title: "Magic Link Generated",
    description:
      "The system generates a unique, secure token and creates a one-time-use magic link.",
    color: "from-accent/20 to-primary/20",
  },
  {
    icon: Mail,
    step: "03",
    title: "Email Delivered",
    description:
      "The magic link is sent to the user's email inbox. The link expires after a set time.",
    color: "from-primary/20 to-accent/20",
  },
  {
    icon: CheckCircle,
    step: "04",
    title: "Click & Logged In",
    description:
      "User clicks the link, the token is verified, and they're instantly authenticated.",
    color: "from-accent/20 to-primary/20",
  },
];

const HowItWorksSection = () => {
  return (
    <section id="projects" className="py-24 md:py-32 bg-gradient-subtle relative">
      <div className="container mx-auto px-6">
        {/* Section Header */}
        <div className="max-w-3xl mx-auto text-center mb-16">
          <span className="text-primary font-body text-sm tracking-widest uppercase mb-4 block">
            The Process
          </span>
          <h2 className="text-3xl md:text-4xl lg:text-5xl font-display font-bold mb-6">
            How It <span className="text-gradient">Works</span>
          </h2>
          <p className="text-muted-foreground font-body text-lg leading-relaxed">
            A simple 4-step flow that makes authentication effortless. 
            Here's exactly what happens behind the scenes.
          </p>
        </div>

        {/* Steps Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {steps.map((item) => (
            <div
              key={item.title}
              className="group relative rounded-2xl overflow-hidden bg-card border border-border hover:border-primary/30 transition-all duration-500 shadow-card hover:shadow-glow"
            >
              {/* Step Number Background */}
              <div
                className={`aspect-video bg-gradient-to-br ${item.color} relative overflow-hidden flex items-center justify-center`}
              >
                <span className="text-8xl font-display font-bold text-foreground/10">
                  {item.step}
                </span>
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-20 h-20 rounded-full bg-background/90 flex items-center justify-center shadow-lg">
                    <item.icon className="w-10 h-10 text-primary" />
                  </div>
                </div>
              </div>

              {/* Step Info */}
              <div className="p-6">
                <div className="flex items-center gap-3 mb-2">
                  <span className="text-xs font-body text-primary font-semibold tracking-wider">
                    STEP {item.step}
                  </span>
                </div>
                <h3 className="text-xl font-display font-semibold mb-2 text-foreground group-hover:text-gradient transition-all duration-300">
                  {item.title}
                </h3>
                <p className="text-muted-foreground font-body text-sm leading-relaxed">
                  {item.description}
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default HowItWorksSection;
